CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role text NOT NULL, PRIMARY KEY(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_usage_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin'); $$;
REVOKE ALL ON FUNCTION public.is_usage_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_usage_admin() TO authenticated, service_role;
CREATE TABLE public.visitor_ai_settings (user_id uuid PRIMARY KEY, daily_budget_usd numeric NOT NULL DEFAULT 1, timezone text NOT NULL DEFAULT 'UTC', adult_confirmed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.visitor_ai_settings TO authenticated;
GRANT ALL ON public.visitor_ai_settings TO service_role;
ALTER TABLE public.visitor_ai_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_settings_read ON public.visitor_ai_settings FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY own_settings_insert ON public.visitor_ai_settings FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY own_settings_update ON public.visitor_ai_settings FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.visitor_ai_keys (user_id uuid NOT NULL, provider text NOT NULL, ciphertext text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id, provider));
GRANT ALL ON public.visitor_ai_keys TO service_role;
ALTER TABLE public.visitor_ai_keys ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.visitor_ai_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, buddy text NOT NULL, provider text NOT NULL, model text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), outcome text NOT NULL DEFAULT 'pending', input_tokens bigint, output_tokens bigint, estimated_usd numeric, rate_version text, modality_usage jsonb);
GRANT SELECT ON public.visitor_ai_events TO authenticated;
GRANT ALL ON public.visitor_ai_events TO service_role;
ALTER TABLE public.visitor_ai_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_or_admin_events ON public.visitor_ai_events FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.is_usage_admin());
CREATE INDEX visitor_ai_events_user_time ON public.visitor_ai_events(user_id, created_at DESC);
CREATE TABLE public.visitor_site_visits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.visitor_site_visits TO authenticated;
GRANT ALL ON public.visitor_site_visits TO service_role;
ALTER TABLE public.visitor_site_visits ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_visits ON public.visitor_site_visits FOR SELECT TO authenticated USING (public.is_usage_admin());
CREATE INDEX visitor_site_visits_user_time ON public.visitor_site_visits(user_id, created_at DESC);
CREATE FUNCTION public.validate_visitor_ai_settings() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.daily_budget_usd <= 0 OR NEW.daily_budget_usd > 100000 THEN RAISE EXCEPTION 'Daily budget must be positive and at most 100000 USD'; END IF; IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = NEW.timezone) THEN RAISE EXCEPTION 'Unknown timezone'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_visitor_settings BEFORE INSERT OR UPDATE ON public.visitor_ai_settings FOR EACH ROW EXECUTE FUNCTION public.validate_visitor_ai_settings();